/**
 * Abandoned-cart recovery routes  (PUBLIC — no auth)
 * ==================================================
 * Backs the recovery links embedded in abandoned-cart emails. The storefront
 * component src/components/CartRecovery.js calls:
 *
 *   GET /api/abandoned-cart/recovery/:token
 *
 * The :token is the 32-byte CSPRNG recovery_token generated by
 * AbandonedCartService.generateRecoveryToken() and stored (UNIQUE) on
 * abandoned_cart_recovery. Possessing the token is therefore the capability that
 * authorizes reading the associated cart — no session/auth required, the same way
 * the one-click unsubscribe links work.
 *
 * On a valid token we mark the cart recovered (AbandonedCartService.markCartRecovered,
 * idempotent — it only flips a row whose recovered_at IS NULL and also cancels any
 * still-pending recovery emails) and return the cart contents plus a redirect target
 * so the client can send the shopper on to checkout.
 *
 * Mount (server.js):  app.use('/api/abandoned-cart', require('./routes/abandonedCartRoutes'));
 * Proxy (next.config.mjs): 'abandoned-cart' is already in the rewrite allowlist.
 */

const express = require('express');
const router = express.Router();
const DatabaseUtil = require('../utils/database');
const ResponseFormatter = require('../utils/responseFormatter');
const AbandonedCartService = require('../services/abandonedCartService');

// Reuse the one shared service instance (see AbandonedCartService.getShared) so this
// route module does not spin up a second background detection/queue interval.
const abandonedCartService = AbandonedCartService.getShared();

// GET /api/abandoned-cart/recovery/:token
router.get('/recovery/:token', async (req, res) => {
  try {
    const token = typeof req.params.token === 'string' ? req.params.token.trim() : '';
    // recovery_token is 64 hex chars (crypto.randomBytes(32)). Bound the input so a
    // junk / oversized value is rejected before it ever reaches the database.
    if (!token || token.length < 16 || token.length > 255) {
      return res.status(400).json(ResponseFormatter.failure('Invalid recovery link'));
    }

    const recoveryResult = await DatabaseUtil.executeQuery(
      'SELECT id, cart_id, email, recovered_at FROM abandoned_cart_recovery WHERE recovery_token = ? LIMIT 1',
      [token]
    );
    const recovery = DatabaseUtil.first(recoveryResult);

    // No match -> disclose nothing beyond "the link is bad" (same as an expired link).
    if (!recovery) {
      return res
        .status(404)
        .json(ResponseFormatter.failure('This recovery link is invalid or has expired'));
    }

    // Mark the cart recovered (idempotent) and cancel any still-pending recovery
    // emails for the address. Best-effort — a failure here must not stop us from
    // handing the shopper back their cart.
    try {
      await abandonedCartService.markCartRecovered(recovery.cart_id, null);
    } catch (markErr) {
      console.error('Non-fatal: markCartRecovered failed during recovery:', markErr.message);
    }

    // Return the cart contents so the client can restore / preview them.
    const itemsResult = await DatabaseUtil.executeQuery(
      `SELECT ci.product_id, ci.variant_id, ci.quantity, ci.price, p.name
       FROM cart_items ci
       JOIN products p ON ci.product_id = p.id
       WHERE ci.cart_id = ?`,
      [recovery.cart_id]
    );
    const items = DatabaseUtil.rows(itemsResult);

    return res.json(
      ResponseFormatter.success('Cart recovered', {
        cartId: recovery.cart_id,
        items,
        itemCount: items.length,
        // Send shoppers with a live cart straight to checkout; an empty / cleared
        // cart (e.g. already purchased) just returns them to the cart page.
        redirectTo: items.length > 0 ? '/checkout' : '/cart',
      })
    );
  } catch (error) {
    console.error('Error processing cart recovery:', error);
    return res.status(500).json(ResponseFormatter.failure('Failed to process cart recovery'));
  }
});

module.exports = router;
